CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `ecommerce_portfolio`.`vw_valid_sales_orders` AS select `o`.`order_id` AS `order_id`,`o`.`customer_id` AS `customer_id`,`o`.`order_date` AS `order_date`,year(`o`.`order_date`) AS `order_year`,month(`o`.`order_date`) AS `order_month`,`o`.`order_status` AS `order_status`,`o`.`sales_channel` AS `sales_channel`,`o`.`shipping_city` AS `shipping_city`,`o`.`shipping_state` AS `shipping_state`,sum(`oi`.`quantity`) AS `units_sold`,sum((`oi`.`quantity` * `oi`.`unit_price`)) AS `sales_revenue` from (`ecommerce_portfolio`.`orders` `o` join `ecommerce_portfolio`.`order_items` `oi` on((`o`.`order_id` = `oi`.`order_id`))) where ((`o`.`order_status` in ('Completed','Shipped')) and exists(select 1 from `ecommerce_portfolio`.`payments` `p` where ((`p`.`order_id` = `o`.`order_id`) and (`p`.`payment_status` = 'Paid'))) and exists(select 1 from `ecommerce_portfolio`.`payments` `p` where ((`p`.`order_id` = `o`.`order_id`) and (`p`.`payment_status` = 'Refunded'))) is false) group by `o`.`order_id`,`o`.`customer_id`,`o`.`order_date`,`o`.`order_status`,`o`.`sales_channel`,`o`.`shipping_city`,`o`.`shipping_state`